import {NUTRIENTS,FOODS,SOURCES,DATA_NOTE} from './nutrition-data.js';
import {MEALS,uid,dateKey,shiftDate,fmt,escapeHTML as esc,emptyState,totals,daily,daysSummary,average,cleanFood,validateBackup,recipeFood,fromOpenFoodFacts} from './core.js';

const $=s=>document.querySelector(s), STORAGE='voedkompas-v1';
let state=emptyState(),loadError='',rawBackup='';
try{rawBackup=localStorage.getItem(STORAGE)||'';if(rawBackup)state=validateBackup(JSON.parse(rawBackup),NUTRIENTS);}catch(e){loadError='Je opgeslagen gegevens konden niet worden geladen. Ze zijn bewaard. Exporteer het herstelbestand bij Instellingen of importeer een geldige back-up.';}
let page=['overview','diary','nutrients','trends','library','settings'].includes(location.hash.slice(1))?location.hash.slice(1):'overview';
let selectedDate=dateKey(),nutrientGroup='vitamin',nutrientSearch='',libraryCategory='Alles',librarySearch='',trendLength=7,trendNutrient='energy',demo=false,realState=null,installPrompt=null,addTab='search',addMeal='Ontbijt',selectedFood=null,editEntryId=null,recipeParts=[],barcodeBusy=false;
const nutrientById=id=>NUTRIENTS.find(n=>n.id===id);
const allFoods=()=>[...state.foods,...FOODS.filter(f=>!state.foods.some(c=>c.id===f.id))];
const target=n=>n.id==='water'?(state.goals.water||state.profile.waterGoal||n.target):(state.goals[n.id]||n.target);
const pct=(v,t)=>Math.min(100,Math.max(0,v/t*100));
const precision=n=>['energy','water'].includes(n.id)?0:2;
const groups={macro:'Voedingswaarden',vitamin:'Vitamines',mineral:'Mineralen'};
const pageNames={overview:'Overzicht',diary:'Dagboek',nutrients:'Voedingsstoffen',trends:'Inzichten',library:'Producten',settings:'Instellingen'};
const icons={
 grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
 book:'<path d="M12 6c-3-2-6-2-9-1v14c3-1 6-1 9 1 3-2 6-2 9-1V5c-3-1-6-1-9 1Z"/><path d="M12 6v14"/>',
 leaf:'<path d="M20 3C9 2 3 7 4 14c1 7 12 9 15 1 1-3 0-8 1-12Z"/><path d="m3 21 12-12M8 16v-5m0 5h5"/>',
 chart:'<path d="M4 3v18h17M8 16l4-5 4 2 5-7"/>',
 box:'<path d="m3 7 9-4 9 4v11l-9 4-9-4V7Zm0 0 9 4 9-4M12 11v11M7 5l10 4"/>',
 gear:'<circle cx="12" cy="12" r="3"/><path d="m10 3-1 3-3 1-3 1 1 4-1 4 3 1 3 1 1 3h4l1-3 3-1 3-1-1-4 1-4-3-1-3-1-1-3Z"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',left:'<path d="m14 6-6 6 6 6"/>',right:'<path d="m10 6 6 6-6 6"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',
 fire:'<path d="M13 2c3 7-4 7-3 12-3 0-4-2-4-4-6 9 2 14 8 11 8-4 3-11 2-12 0 4-2 5-3 5 3-6 2-9 0-12Z"/>',
 protein:'<path d="M4 8v8m3-11v14m10-14v14m3-11v8M7 12h10"/>',grain:'<path d="m5 21 14-16M9 17c-5 0-6-3-5-6 3 0 6 1 5 6Zm4-5c-4-1-5-4-3-7 3 1 4 4 3 7Zm1 0c0 5 3 6 6 5 0-3-2-5-6-5Zm4-6c-1-4 1-5 4-5 0 3-1 5-4 5Z"/>',
 drop:'<path d="M12 2C9 7 4 11 4 15a8 8 0 0 0 16 0c0-4-5-8-8-13Z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>',
 lunch:'<path d="M3 14a9 9 0 0 1 18 0H3Zm-1 4h20M12 3v2"/>',moon:'<path d="M20 14A9 9 0 0 1 10 3a9 9 0 1 0 10 11Z"/>',apple:'<path d="M12 7C5 2 1 9 4 17c2 5 5 4 8 3 3 1 6 2 8-3 3-8-1-15-8-10Zm0 0c0-4 3-6 6-5 0 3-2 5-6 5Z"/>',pill:'<path d="m8 3 13 13a5 5 0 0 1-7 7L1 10A5 5 0 0 1 8 3Zm0 7 6-6" transform="translate(2 -1) scale(.88)"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',phone:'<rect x="6" y="2" width="12" height="20" rx="2"/><path d="M10 18h4"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m16 16 5 5"/>',star:'<path d="m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z"/>',trash:'<path d="M4 6h16M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7"/>',edit:'<path d="m4 15-1 6 6-1L21 8l-5-5L4 15Zm9-9 5 5"/>',check:'<path d="m4 12 5 5L20 6"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/>',barcode:'<path d="M3 4v16M6 4v16M10 4v16m3-16v16m5-16v16m3-16v16"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/>'};
const icon=(name,cl='')=>`<svg class="icon ${cl}" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.leaf}</svg>`;
const navItems=[['overview','grid','Overzicht'],['diary','book','Dagboek'],['nutrients','leaf','Voedingsstoffen'],['trends','chart','Inzichten'],['library','box','Producten']];
const mealIcon=['sun','lunch','moon','apple','pill'];
const current=()=>daily(state,selectedDate,NUTRIENTS);
function save(){if(demo)return;if(loadError){toast('Herstel eerst je opgeslagen gegevens via Instellingen.');return;}try{localStorage.setItem(STORAGE,JSON.stringify(state));}catch(e){toast('Opslaan is niet gelukt. Exporteer een back-up voordat je afsluit.');}}
function toast(message,undo){const t=document.createElement('div');t.className='toast';t.textContent=message;if(undo){const b=document.createElement('button');b.textContent='Ongedaan maken';b.onclick=()=>{undo();t.remove();};t.append(b);}$('#toasts').append(t);setTimeout(()=>t.remove(),undo?10000:5500);}
function go(p){if(!pageNames[p])return;page=p;if(location.hash.slice(1)!==p)history.replaceState(null,'','#'+p);render();window.scrollTo({top:0,behavior:'instant'});}
function dateControl(){return `<div class="date-switch"><button class="icon-button" data-action="day" data-value="-1" aria-label="Vorige dag">${icon('left')}</button><input id="selected-date" type="date" value="${selectedDate}" aria-label="Dag selecteren"><button class="icon-button" data-action="day" data-value="1" aria-label="Volgende dag">${icon('right')}</button></div>`;}
function render(){
  const name=state.profile.name?`, ${esc(state.profile.name)}`:'';
  $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#overview" data-page="overview"><img src="./icon.svg" alt=""> <span>Voed<span>Kompas</span></span></a><div class="tagline">Je dagelijkse dosis inzicht.</div><div class="nav-label">MIJN GEZONDHEID</div><nav class="nav" aria-label="Hoofdnavigatie">${navItems.map(([id,ic,label])=>`<button data-page="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(ic)}${label}</button>`).join('')}</nav><div class="sidebar-bottom"><nav class="nav"><button data-page="settings" class="${page==='settings'?'active':''}">${icon('gear')}Instellingen</button></nav><div class="install-card">${icon('phone')}<h3>Jouw kompas, altijd bij je.</h3><p>Neem je dagboek mee.<br>Ook zonder internet.</p><button data-action="install">${window.AndroidBridge?'Over deze Android-app':'App installeren'} ↗</button></div><div class="local-label"><i></i>Privé opgeslagen op dit apparaat</div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">Mijn gezondheid <span> / &nbsp; ${pageNames[page]}</span></div><div class="mobile-brand"><img src="./icon.svg" alt="">VoedKompas</div><div class="user-pill"><span><i class="offline-dot"></i>${navigator.onLine?'Klaar voor jouw dag':'Je werkt offline'}</span><button class="icon-button" data-page="settings" aria-label="Instellingen">${icon('gear')}</button><span class="avatar">${esc((state.profile.name||'Jij').slice(0,2).toUpperCase())}</span></div></header><main class="content" id="main">${demo?'<div class="demo-banner"><span>Voorbeeldmodus · fictief dagboek, geen eigen registraties.</span><button data-action="exit-demo">Voorbeeld sluiten</button></div>':''}${loadError?`<div class="notice error mb16">${esc(loadError)} <button class="text-button" data-page="settings">Naar instellingen</button></div>`:''}${({overview:()=>overview(name),diary:diaryPage,nutrients:nutrientsPage,trends:trendsPage,library:libraryPage,settings:settingsPage}[page])()}<footer class="page-footer"><span>${icon('leaf')} VoedKompas · Kleine inzichten. Bewuste keuzes.</span><span>Voedingsinname is geen diagnose · <a href="#settings" data-page="settings">Bronnen & privacy</a></span></footer></main></div><nav class="mobile-nav" aria-label="Mobiele navigatie">${navItems.map(([id,ic,label])=>`<button data-page="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(ic)}${id==='nutrients'?'Voedingsstoffen':label}</button>`).join('')}</nav></div>`;
}
function heading(title,sub,actions=true){return `<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div>${actions?`<div class="row gap8">${dateControl()}<button class="button primary" data-action="add">${icon('plus')}Voeding toevoegen</button></div>`:''}</div>`;}
function metricCards(values){return `<div class="cards">${[['energy','fire'],['protein','protein'],['carbs','grain'],['fat','drop']].map(([id,ic])=>{const n=nutrientById(id),v=values[id];return `<div class="metric"><div class="metric-top"><span class="metric-icon">${icon(ic)}</span>${n.name}</div><div class="metric-number">${v.total&&!v.known?'—':fmt(v.value,precision(n))}<small>${n.unit}</small></div><div class="metric-sub">van ${fmt(target(n),2)} ${n.unit} referentie${v.total&&!v.complete?' · deels bekend':''}</div><div class="bar"><span style="width:${pct(v.value,target(n))}%"></span></div></div>`;}).join('')}</div>`;}
function overview(name){const d=current(),has=d.entries.length>0;return `${heading(`Jouw dag${name}.`,'Meer inzicht in je voeding. Meer grip op je balans.')}<div class="overview-grid"><div class="stack"><section class="hero"><div><div class="eyebrow">ELKE MAALTIJD TELT</div><h2>${has?'Je voeding, in een<br>breder perspectief.':'Goed voor jezelf<br>begint met inzicht.'}</h2><p>${has?`${d.entries.length} producten vastgelegd. Ontdek wat je maaltijden aan vitamines en mineralen bijdragen.`:'Van energie tot zink. Ontdek wat je binnenkrijgt en leer je voeding beter kennen.'}</p><button class="button primary small" data-action="${has?'all-nutrients':'add'}">${has?'Bekijk je voedingsstoffen':'Begin met je eerste maaltijd'} ${icon('arrow')}</button></div><div class="hero-art" aria-hidden="true"><svg viewBox="0 0 200 170"><ellipse cx="105" cy="149" rx="77" ry="9" fill="#ced9b8"/><path d="M29 83h147c-5 56-35 64-74 64-40 0-66-14-73-64Z" fill="#f8f9eb"/><ellipse cx="102" cy="83" rx="74" ry="20" fill="#c0cf9e"/><path d="M101 91C62 90 38 61 54 31c37-7 69 20 47 60Z" fill="#71975d"/><path d="M101 91c-8-39 17-67 51-60 14 34-14 60-51 60Z" fill="#99b576"/><path d="M100 93c-4-32-22-57-33-65m34 64c5-20 21-40 36-47" fill="none" stroke="#547e4e" stroke-width="2"/><ellipse cx="65" cy="83" rx="23" ry="14" fill="#e7b67b"/><ellipse cx="138" cy="86" rx="24" ry="13" fill="#c88155"/><path d="m151 43 22-13m-14 25 22-4M25 54l-11-7" stroke="#8ca273" stroke-width="2" stroke-linecap="round"/><circle cx="33" cy="30" r="3" fill="#c9d4b4"/><circle cx="175" cy="75" r="3" fill="#c9d4b4"/></svg></div></section>${metricCards(d.values)}<section class="card"><div class="card-heading"><div><h2>Op je bord vandaag</h2><p>Een goed overzicht begint bij je maaltijden.</p></div><button class="text-button" data-page="diary">Dagboek ${icon('right')}</button></div>${mealsHTML(d.entries,false)}${!has?`<div class="tip mt16">${icon('info')}Nieuw hier? <button class="text-button" data-action="demo">Bekijk een ingevuld voorbeeld</button></div>`:''}</section></div><div class="stack"><section class="card"><div class="card-heading"><div><h2>Je voedingsstoffen</h2><p>Een blik op je dagelijkse inname.</p></div><span class="badge">${selectedDate===dateKey()?'Vandaag':'Deze dag'}</span></div>${['vitaminC','vitaminD','vitaminB12','calcium','magnesium','zinc'].map(id=>nutrientRow(nutrientById(id),d.values[id])).join('')}<button class="button ghost small mt16" style="width:100%" data-page="nutrients">Alle 27 vitamines & mineralen ${icon('arrow')}</button><div class="tip mt16">${icon('info')}Een lage registratie is geen vastgesteld tekort. Kijk naar je patroon over meerdere dagen.</div></section>${waterCard()}<section class="card insight-card"><div class="eyebrow">GOED OM TE WETEN</div><h2>Wat doet zink voor je?</h2><p>Zink ondersteunt je afweer en wondgenezing. Ontdek wat een werkelijk tekort kan betekenen en in welke voeding je zink vindt.</p><button class="text-button" data-action="nutrient" data-id="zinc">Meer over zink ${icon('arrow')}</button></section></div></div>`;}
function symbol(n){return ({vitaminA:'A',vitaminD:'D',vitaminE:'E',vitaminK:'K',vitaminC:'C',vitaminB1:'B1',vitaminB2:'B2',vitaminB3:'B3',vitaminB6:'B6',folate:'B11',vitaminB12:'B12',biotin:'B8',vitaminB5:'B5',calcium:'Ca',magnesium:'Mg',zinc:'Zn',iron:'Fe',potassium:'K',chloride:'Cl',phosphorus:'P',copper:'Cu',manganese:'Mn',fluoride:'F',selenium:'Se',chromium:'Cr',molybdenum:'Mo',iodine:'I'})[n.id]||'◌';}
function coverage(v){return !v.total?'Nog geen voeding geregistreerd':!v.known?'Geen waarden bekend':v.complete?'Alle ingevoerde producten bekend':`${v.known} van ${v.total} producten bekend`;}
function nutrientRow(n,v){return `<button class="nutrient-row" data-action="nutrient" data-id="${n.id}"><div class="row"><span class="circle-letter">${symbol(n)}</span><div class="grow"><div class="row between gap8"><span class="name">${n.name}</span><span class="value">${v.known?fmt(v.value,precision(n)):'—'} / ${fmt(target(n),2)} ${n.unit}</span></div><div class="bar"><span style="width:${pct(v.value,target(n))}%"></span></div><div class="coverage">${coverage(v)}</div></div></div></button>`;}
function mealsHTML(entries,full){return MEALS.filter((m,i)=>full||i<4||entries.some(e=>e.meal===m)).map((m,i)=>{const list=entries.filter(e=>e.meal===m),t=totals(list,NUTRIENTS);return `<div class="meal"><div class="row"><div class="meal-icon">${icon(mealIcon[i])}</div><div class="grow"><h3>${m}</h3><p>${list.length?`${list.length} ${list.length===1?'product':'producten'} · ${t.energy.known?fmt(t.energy.value):'—'} kcal${t.energy.complete?'':' · deels bekend'}`:'Nog niets toegevoegd'}</p></div><button class="add-circle" data-action="add" data-meal="${m}" aria-label="Toevoegen aan ${m}">${icon('plus')}</button></div>${list.map(e=>`<div class="food-entry"><span class="food-emoji">${esc(e.food.emoji||'🥣')}</span><div class="grow"><h4>${esc(e.food.name)}</h4><p>${fmt(e.amount,1)} ${e.food.basis==='dose'?'dosis':'g'}${e.food.category==='Recepten'?' · recept':''}</p></div><span class="amount">${e.food.values.energy==null?'—':fmt(e.food.values.energy*e.amount/(e.food.basis==='dose'?1:100))} kcal</span><button class="icon-button" data-action="edit-entry" data-id="${esc(e.id)}" aria-label="Hoeveelheid aanpassen: ${esc(e.food.name)}">${icon('edit')}</button>${full?`<button class="icon-button" data-action="delete-entry" data-id="${esc(e.id)}" aria-label="Verwijderen: ${esc(e.food.name)}">${icon('trash')}</button>`:''}</div>`).join('')}</div>`;}).join('');}
function waterCard(){const ml=state.water[selectedDate]||0,goal=target(nutrientById('water'));return `<section class="card water-card"><div class="row between"><div><h2>Een slokje aandacht</h2><p class="small muted mt8">Je dranken van vandaag.</p></div>${icon('drop')}</div><div class="water-drops">${Array.from({length:8},(_,i)=>`<svg class="${ml/goal*8>=i+1?'filled':''}" viewBox="0 0 24 28" aria-hidden="true"><path d="M12 2C9 7 4 12 4 17a8 8 0 0 0 16 0c0-5-5-10-8-15Z"/></svg>`).join('')}</div><div class="water-amount">${fmt(ml)} <span>/ ${fmt(goal)} ml</span></div><div class="water-actions mt16"><button class="button" data-action="water" data-value="250">+ 250 ml</button><button class="button" data-action="water" data-value="500">+ 500 ml</button><button class="button" data-action="water-edit" aria-label="Drinkregistratie aanpassen">${icon('edit')}</button></div><p class="tiny muted mt8">Dranken apart registreren; voeding telt hier niet automatisch mee.</p></section>`;}
function diaryPage(){const d=current(),done=state.completed.includes(selectedDate);return `${heading('Je voedingsdagboek.','Leg vast wat je eet, op jouw manier.')}<div class="stack">${metricCards(d.values)}<div class="two-col"><section class="card"><div class="card-heading"><h2>Maaltijden & supplementen</h2><button class="text-button" data-action="copy-day">${icon('copy')}Kopieer gisteren</button></div>${mealsHTML(d.entries,true)}</section><div class="stack">${waterCard()}<section class="card"><div class="card-heading"><h2>Hoe was je dag?</h2>${icon('book')}</div><label class="field">Persoonlijke notitie<textarea class="notes-area" id="day-notes" maxlength="3000" placeholder="Bijvoorbeeld: drukke dag, gesport, weinig trek…">${esc(state.notes[selectedDate]||'')}</textarea></label><button class="button secondary small mt16" data-action="save-note">Notitie opslaan</button><div class="mt24"><button class="button ${done?'soft':'ghost'}" style="width:100%" data-action="complete-day">${icon('check')}${done?'Dag als volledig gemarkeerd':'Dag compleet vastgelegd'}</button><p class="tiny muted mt8">Een vinkje betekent dat jij klaar bent met invoeren, niet dat je voeding compleet is.</p></div></section><section class="notice">Supplementen kun je per dosis toevoegen. Tel alleen wat je daadwerkelijk hebt genomen en neem hoeveelheden en eenheden over van het etiket.</section></div></div></div>`;}
function nutrientsPage(){const d=current(),list=NUTRIENTS.filter(n=>n.group===nutrientGroup&&n.name.toLowerCase().includes(nutrientSearch.toLowerCase()));return `${heading('Meer dan calorieën.','Ontdek je vitamines, mineralen en andere voedingsstoffen.')}<div class="row between wrap mb16"><div class="tabs" role="tablist">${Object.entries(groups).map(([id,label])=>`<button role="tab" aria-selected="${nutrientGroup===id}" class="${nutrientGroup===id?'active':''}" data-action="nutrient-group" data-id="${id}">${label} <span class="muted">${NUTRIENTS.filter(n=>n.group===id).length}</span></button>`).join('')}</div></div><div class="notice mb16">Percentages vergelijken je ingevoerde voeding met EU-etiketreferenties voor volwassenen. Dit zijn geen persoonlijke adviezen of tekortgrenzen. Onbekende waarden blijven onbekend.</div><div class="nutrient-grid">${list.map(n=>{const v=d.values[n.id];return `<button class="nutrient-tile" data-action="nutrient" data-id="${n.id}"><div class="row between"><span class="circle-letter">${symbol(n)}</span><span class="badge ${v.total&&!v.complete?'amber':''}">${n.kind==='limit'?'Grens':v.total&&!v.complete?'Deels bekend':n.kind==='minimum'&&v.complete&&v.value<target(n)?'Onder referentie':'Referentie'}</span></div><h3>${n.name}</h3><div class="big">${v.known?fmt(v.value,precision(n)):'—'}<small>${n.unit}</small></div><p>Referentie: ${fmt(target(n),2)} ${n.unit}${state.goals[n.id]?' · aangepast':''}</p><div class="bar"><span style="width:${pct(v.value,target(n))}%;${n.kind==='limit'&&v.value>target(n)?'background:#bd8551':''}"></span></div><div class="row between"><span class="tiny muted">${v.total?coverage(v):'Nog niets ingevoerd'}</span><span class="progress-pct">${v.known?fmt(v.value/target(n)*100)+'%':'—'}</span></div></button>`;}).join('')}</div>`;}
function trendsPage(){const days=daysSummary(state,selectedDate,trendLength,NUTRIENTS),n=nutrientById(trendNutrient),a=average(days,n.id),recorded=days.filter(d=>d.entries.length).length,done=days.filter(d=>d.completed).length,max=Math.max(target(n)*1.1,...days.map(d=>d.values[n.id].value))*1.05;return `${heading('Kijk naar het grotere geheel.','Je patroon vertelt meer dan één losse dag.',false)}<div class="row between wrap mb16">${dateControl()}<div class="row gap8"><select id="trend-nutrient" class="input" aria-label="Voedingsstof voor grafiek">${NUTRIENTS.filter(n=>n.id!=='water').map(n=>`<option value="${n.id}" ${n.id===trendNutrient?'selected':''}>${n.name}</option>`).join('')}</select><div class="tabs"><button class="${trendLength===7?'active':''}" data-action="range" data-value="7">7 dagen</button><button class="${trendLength===30?'active':''}" data-action="range" data-value="30">30 dagen</button></div></div></div><div class="trend-stats"><div class="trend-stat"><div class="label">Dagen met voeding</div><strong>${recorded}<span> / ${trendLength}</span></strong><span>Lege dagen tellen niet als nul</span></div><div class="trend-stat"><div class="label">Gemiddeld ${n.name.toLowerCase()}</div><strong>${fmt(a.value,precision(n))}</strong><span>${n.unit} · ${a.days} dagen met waarden</span></div><div class="trend-stat"><div class="label">Volledig vastgelegd</div><strong>${done}</strong><span>Door jou gemarkeerde dagen</span></div></div><div class="stack"><section class="card"><div class="card-heading"><div><h2>${n.name} door de tijd</h2><p>Bekende inname per geregistreerde dag · ${n.unit}</p></div><span class="badge">${a.complete?'Waarden bekend':'Let op datadekking'}</span></div><div class="chart-space"><div class="chart" role="img" aria-label="Staafdiagram met ${n.name.toLowerCase()} per dag. Exacte waarden staan in de tabel hieronder.">${days.map((d,i)=>`<div class="chart-col ${d.date===selectedDate?'current':''}"><span class="chart-val">${trendLength===7?(d.values[n.id].known?fmt(d.values[n.id].value):'—'):''}</span><div class="chart-bar" style="height:${d.entries.length?Math.max(2,d.values[n.id].value/max*160):2}px;${!d.entries.length?'background:#e8ecdf':''}"></div><span class="chart-label">${trendLength===7?new Date(d.date+'T12:00:00').toLocaleDateString('nl-NL',{weekday:'short'}):i%5===0?d.date.slice(8):''}</span></div>`).join('')}</div></div><div class="notice">${!recorded?'Voeg voeding toe in je dagboek om je eerste inzichten te zien.':`Gemiddelde op basis van ${a.days} dagen met bekende waarden. Gedeeltelijk ingevulde dagen en ontbrekende productwaarden kunnen dit gemiddelde verlagen. Een vergelijking met de referentie stelt geen tekort vast.`}</div><div class="scroll-table mt16"><table class="history-table"><thead><tr><th>Dag</th><th>${n.name}</th><th>Gegevensdekking</th><th>Dagboek</th></tr></thead><tbody>${[...days].reverse().map(d=>`<tr><td><button data-action="open-day" data-date="${d.date}">${new Date(d.date+'T12:00:00').toLocaleDateString('nl-NL',{day:'numeric',month:'short'})}</button></td><td>${d.values[n.id].known?`${fmt(d.values[n.id].value,precision(n))} ${n.unit}`:'—'}</td><td>${coverage(d.values[n.id])}</td><td>${d.completed?'Compleet gemarkeerd':d.entries.length?'Geregistreerd':'Leeg'}</td></tr>`).join('')}</tbody></table></div></section><section class="card"><div class="card-heading"><h2>Vitamines & mineralen gemiddeld</h2><span class="badge">Bekende waarden</span></div><div class="food-grid">${NUTRIENTS.filter(n=>n.group!=='macro').map(n=>{const a=average(days,n.id);return `<button class="nutrient-row" data-action="nutrient" data-id="${n.id}"><div class="row between"><span class="name">${n.name}</span><span class="value">${fmt(a.value,precision(n))} ${n.unit} · ${a.days} d.</span></div><div class="bar"><span style="width:${pct(a.value||0,target(n))}%"></span></div><span class="coverage">${a.value===null?'Geen waarden':`${fmt(a.value/target(n)*100)}% van referentie${a.complete?'':' · onvolledige gegevens'}`}</span></button>`;}).join('')}</div></section></div>`;}
function foodItem(f,action='choose-food'){const custom=state.foods.some(x=>x.id===f.id);return `<button class="food-item" data-action="${action}" data-id="${esc(f.id)}"><span class="food-emoji">${esc(f.emoji||'🥣')}</span><div class="grow"><h3>${esc(f.name)}</h3><p>${esc(custom?f.sourceName||'Eigen product':f.category)}${state.favorites.includes(f.id)?' · ★':''}</p></div><div class="food-kcal">${f.values.energy==null?'—':fmt(f.values.energy)}<small>kcal / ${f.basis==='dose'?'dosis':'100 g'}</small></div>${icon('right')}</button>`;}
function filterFoods(query,category){return allFoods().filter(f=>(!query||`${f.name} ${f.category}`.toLowerCase().includes(query.toLowerCase()))&&(category==='Alles'||category==='Favorieten'&&state.favorites.includes(f.id)||category==='Eigen producten'&&state.foods.some(x=>x.id===f.id)||f.category===category));}
function libraryResults(){const list=filterFoods(librarySearch,libraryCategory);return list.length?list.map(f=>foodItem(f,'food-detail')).join(''):'<div class="empty">Geen producten gevonden. Voeg zelf een product toe of zoek met een barcode.</div>';}
function libraryPage(){const cats=['Alles','Favorieten','Eigen producten',...new Set(FOODS.map(f=>f.category)),'Recepten'];return `${heading('Jouw voedingsbibliotheek.','Betrouwbare basisproducten, je eigen favorieten en recepten.',false)}<div class="row wrap library-toolbar mb16"><div class="search">${icon('search')}<input class="input" id="library-search" value="${esc(librarySearch)}" placeholder="Zoek een product…" aria-label="Zoek een product"></div><button class="button secondary" data-action="new-recipe">${icon('book')}Recept maken</button><button class="button primary" data-action="new-food">${icon('plus')}Eigen product</button></div><div class="library-filters">${cats.map(c=>`<button class="chip ${libraryCategory===c?'active':''}" data-action="library-category" data-value="${esc(c)}">${esc(c)}</button>`).join('')}</div><div class="food-grid" id="library-results">${libraryResults()}</div><div class="notice mt24">${FOODS.length} basisproducten uit CoFID (2021). Waarden zijn gemiddelden per 100 g eetbaar product; merken en bereidingswijzen verschillen. Controleer het etiket. Meer producten toevoegen kan via een barcode of eigen invoer.</div>`;}
function settingsPage(){return `${heading('Precies zoals jij het wilt.','Je voorkeuren, dagreferenties en gegevens op één plek.',false)}<div class="two-col"><div class="card"><form id="settings-form"><section class="settings-section"><h3>Een persoonlijk kompas</h3><p>Alle gegevens blijven lokaal. Er is geen account of automatische synchronisatie tussen apparaten.</p><label class="field">Hoe mogen we je noemen?<input name="name" maxlength="60" value="${esc(state.profile.name)}" placeholder="Je voornaam"></label></section><section class="settings-section"><h3>Jouw dagreferenties</h3><p>De standaard is de EU-etiketreferentie voor volwassenen, niet je persoonlijke behoefte. Vezels en drinken hebben aanpasbare voorbeeldwaarden. Niet afgestemd op kinderen, zwangerschap of een medische behandeling.</p><div class="goal-grid">${NUTRIENTS.filter(n=>n.group==='macro').map(goalInput).join('')}</div><details class="mt24"><summary class="small">Vitamines & mineralen aanpassen</summary><div class="goal-grid mt16">${NUTRIENTS.filter(n=>n.group!=='macro').map(goalInput).join('')}</div></details><p class="tiny muted mt16">Vitamine D: 5 µg is de EU-etiketreferentie en kan afwijken van Nederlands voedings- of suppletieadvies. Deze app adviseert geen supplementdoseringen. Zout en verzadigd vet hoef je niet te halen.</p></section><div class="form-actions"><button type="button" class="button ghost" data-action="reset-goals">Standaardwaarden</button><button type="submit" class="button primary">Voorkeuren opslaan</button></div></form></div><div class="stack"><section class="card"><div class="card-heading"><h2>Jouw gegevens</h2>${icon('lock')}</div><p class="small muted" style="line-height:1.8">${state.entries.length} dagboekregels · ${state.foods.length} eigen producten. Maak regelmatig een back-up, vooral voordat je de app verwijdert of van telefoon wisselt.</p><div class="stack mt16" style="gap:9px"><button class="button secondary" data-action="export">${icon('download')}Back-up downloaden (.json)</button><button class="button secondary" data-action="csv">${icon('download')}Dagtotalen exporteren (.csv)</button><button class="button secondary" data-action="import">${icon('upload')}Back-up terugzetten</button>${loadError?'<button class="button danger" data-action="recovery">Herstelbestand downloaden</button>':''}</div><p class="tiny muted mt16">Een back-up bevat je voedingsdagboek en notities. Bewaar hem op een plek die je zelf vertrouwt.</p></section><section class="card"><div class="card-heading"><h2>Over deze app</h2>${icon('phone')}</div><p class="small muted" style="line-height:1.9">VoedKompas 1.0 · Nederlands<br>Offline dagboek, producten en uitleg.<br>Internet nodig voor barcodegegevens en bronpagina’s.</p><button class="button soft mt16" data-action="install">${window.AndroidBridge?'Android-app & privacy':'Installeren op Android'}</button><button class="text-button mt16" data-action="demo">Ingevuld voorbeeld bekijken ${icon('arrow')}</button></section></div></div><section class="card mt24"><div class="card-heading"><h2>Begrijp wat je ziet</h2>${icon('info')}</div><div class="food-grid"><div class="detail-section" style="margin:0"><h3>Inname is geen diagnose</h3><p>Een dag onder de referentie betekent niet dat je een tekort hebt. Voorraden, opname, zonlicht, gezondheid en ontbrekende gegevens spelen mee. De beschreven klachten hebben vaak meerdere oorzaken. Bespreek aanhoudende klachten of een vermoeden van een tekort met je huisarts; een dagboek stelt geen diagnose.</p></div><div class="detail-section" style="margin:0"><h3>Onbekend betekent niet nul</h3><p>We tellen alleen bekende waarden op. Bij elke voedingsstof zie je hoeveel producten gegevens bevatten. Ook een volledig ingevuld dagboek kan onvolledige voedingswaarden bevatten. Weekgemiddelden gebruiken alleen dagen met bekende waarden; lege dagen tellen niet als nul.</p></div></div><div class="detail-section"><h3>Privacy</h3><p>Voeding, notities en voorkeuren worden in deze app op je apparaat bewaard. Geen analytics en geen cloudopslag. Bij een barcodezoekopdracht gaat de opgegeven barcode naar Open Food Facts; daarbij ontvangt die dienst gebruikelijke verbindingsgegevens zoals je IP-adres. Bronlinks openen in je browser. De Android-app vraagt geen opslag-, camera- of locatiepermissies.</p></div><h3 class="mt24">Bronnen & gegevens</h3><ul class="source-list">${sourceLinks()}</ul><p class="small muted" style="line-height:1.8">${esc(typeof DATA_NOTE==='string'?DATA_NOTE:JSON.stringify(DATA_NOTE))}</p><div class="form-actions"><button class="button danger small" data-action="reset-data">Alle lokale gegevens wissen</button></div></section>`;}
function sourceLinks(){return SOURCES.map(s=>typeof s==='string'?`<li><a href="${esc(s)}" target="_blank" rel="noopener">${esc(s)}</a></li>`:`<li><a href="${esc(s.url||s.href||'')}" target="_blank" rel="noopener">${esc(s.title||s.name||s.label||s.url)}</a>${(s.note||s.description)?' — '+esc(s.note||s.description):''}</li>`).join('');}
function goalInput(n){return `<label class="field">${n.name} (${n.unit})<input type="number" name="goal-${n.id}" value="${target(n)}" min="0.001" max="1000000" step="any" required></label>`;}
function modal(title,content){const el=$('#modal');el.innerHTML=`<div class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close-modal" aria-label="Sluiten">${icon('close')}</button></div><div class="modal-content">${content}</div>`;if(!el.open)el.showModal();el.scrollTop=0;}
function closeModal(){$('#modal').close();}
function nutrientDetail(id){const n=nutrientById(id);if(!n)return;const v=current().values[id],suggestions=allFoods().filter(f=>f.basis!=='dose'&&Number.isFinite(f.values[id])&&f.values[id]>0).sort((a,b)=>b.values[id]-a.values[id]).slice(0,4);modal(n.name,`<div class="detail-hero"><span class="circle-letter">${symbol(n)}</span><div><div class="eyebrow">${groups[n.group]}</div><h2 class="mt8">${n.name}</h2><p>${esc(n.about)}</p></div></div><div class="detail-number">${v.known?fmt(v.value,precision(n)):'—'} <span>/ ${fmt(target(n),2)} ${n.unit} referentie</span></div><div class="bar mt16"><span style="width:${pct(v.value,target(n))}%"></span></div><p class="tiny muted mt8">${coverage(v)}${state.goals[id]?' · door jou aangepaste referentie':''}</p><div class="notice">${n.kind==='limit'?'Dit is een grens om mee te vergelijken, geen hoeveelheid die je moet halen.':n.kind==='reference'?'Dit is een referentiewaarde, geen ondergrens of vastgesteld persoonlijk doel.':'Een hoeveelheid onder deze etiketreferentie bewijst geen tekort. Een voedingsdagboek kan de voorraad of opname in je lichaam niet bepalen.'}</div><section class="detail-section"><h3>Wat kan langdurig te weinig betekenen?</h3><p>${esc(n.low)}</p></section>${n.high?`<section class="detail-section"><h3>En te veel?</h3><p>${esc(n.high)}</p></section>`:''}<section class="detail-section"><h3>Waar zit het in?</h3><p>${esc(n.foods)}</p></section>${n.kind==='minimum'&&suggestions.length?`<section class="detail-section"><h3>Uit je voedingsbibliotheek</h3><p>Voorbeelden per 100 g, geen portieadvies.</p><div class="food-list">${suggestions.map(f=>`<button class="food-item" data-action="choose-food" data-id="${esc(f.id)}"><span class="food-emoji">${esc(f.emoji)}</span><span class="grow">${esc(f.name)}</span><span class="small muted">${fmt(f.values[id],precision(n))} ${n.unit}</span>${icon('plus')}</button>`).join('')}</div></section>`:''}<div class="tip">${icon('info')}Deze uitleg is algemene informatie. Aanhoudende klachten of zorgen over een tekort? Bespreek ze met je huisarts. Neem geen hoge supplementdosering op basis van een dagscore.</div><div class="detail-section"><a href="${esc(n.source)}" target="_blank" rel="noopener">Lees de medische bron ↗</a><p class="tiny mt8">${esc(n.targetNote||'EU-etiketreferentie voor volwassenen; geen persoonlijk advies.')}</p><a href="${esc(n.targetSource||n.source)}" target="_blank" rel="noopener">Bron referentiewaarde ↗</a></div>`);}
function openAdd(meal='Ontbijt',tab='search'){addMeal=MEALS.includes(meal)?meal:'Ontbijt';addTab=tab;selectedFood=null;editEntryId=null;renderAdd();}
function renderAdd(){modal('Voeding toevoegen',`<div class="tabs" role="tablist">${[['search','Zoeken'],['barcode','Barcode'],['custom','Eigen product'],['supplement','Supplement']].map(([id,label])=>`<button role="tab" aria-selected="${addTab===id}" class="${addTab===id?'active':''}" data-action="add-tab" data-id="${id}">${label}</button>`).join('')}</div>${addTab==='search'?`<div class="search">${icon('search')}<input id="food-search" class="input" placeholder="Bijvoorbeeld havermout, banaan of ei" aria-label="Voeding zoeken" autofocus></div><div class="row between mt16"><span class="small muted">${allFoods().length} producten beschikbaar</span><button class="text-button" data-action="show-favorites">${icon('star')}Favorieten</button></div><div id="food-results" class="food-list">${allFoods().slice(0,40).map(f=>foodItem(f)).join('')}</div>`:addTab==='barcode'?barcodeForm():customForm(addTab==='supplement')}`);}
function barcodeForm(){return `<form id="barcode-form"><label class="field">Barcode (EAN of UPC)<input name="barcode" inputmode="numeric" pattern="[0-9]{8,14}" minlength="8" maxlength="14" required placeholder="Bijvoorbeeld 871…" autocomplete="off"></label><button type="submit" class="button primary mt16">${icon('barcode')}Product opzoeken</button><p class="small muted mt16" style="line-height:1.8">Typ de cijfers onder de barcode. We zoeken online in Open Food Facts. Controleer de waarden met de verpakking; vitamines en mineralen ontbreken daar vaak.</p><div id="barcode-status" role="status"></div></form>`;}
function customForm(supplement=false,existing=null){const f=existing;return `<form id="custom-form" data-edit="${esc(f?.id||'')}" data-basis="${supplement?'dose':'100g'}"><div class="form-grid"><label class="field">${supplement?'Naam supplement':'Productnaam'}<input name="foodName" maxlength="160" value="${esc(f?.name||'')}" required placeholder="${supplement?'Bijv. multivitamine':'Bijv. mijn volkorenbrood'}"></label><label class="field">${supplement?'Gebruikelijke dosis':'Gebruikelijke portie (g)'}<input name="serving" type="number" min="0.01" max="10000" step="any" value="${f?.serving||(supplement?1:100)}" required></label></div><div class="notice">Vul ${supplement?'de hoeveelheid per 1 dosis (bijvoorbeeld één tablet)':'de waarden per 100 g'} in. Laat onbekende waarden leeg. 0 betekent expliciet nul. Neem de eenheden zorgvuldig over van het etiket.</div><div class="form-grid three">${NUTRIENTS.filter(n=>n.group==='macro'&&n.id!=='water').map(n=>valueInput(n,f)).join('')}</div>${['vitamin','mineral'].map(g=>`<details ${supplement?'open':''}><summary>${groups[g]}</summary><div class="form-grid three">${NUTRIENTS.filter(n=>n.group===g).map(n=>valueInput(n,f)).join('')}</div></details>`).join('')}<div id="custom-error" class="error-text" role="alert"></div><div class="form-actions"><button class="button primary" type="submit">${icon('check')}${f?'Wijzigingen opslaan':'Bewaren & hoeveelheid kiezen'}</button></div></form>`;}
function valueInput(n,f){return `<label class="field">${n.name} (${n.unit})<input type="number" name="nutrient-${n.id}" min="0" max="1000000000" step="any" value="${f?.values?.[n.id]??''}" placeholder="Onbekend"></label>`;}
function chooseFood(id,entryId=null){const entry=entryId?state.entries.find(e=>e.id===entryId):null;selectedFood=entry?.food||allFoods().find(f=>f.id===id);editEntryId=entry?.id||null;if(!selectedFood)return;const f=selectedFood;if(entry)addMeal=entry.meal;modal(entry?'Hoeveelheid aanpassen':'Toevoegen aan je dagboek',`<div class="detail-hero"><span class="food-emoji">${esc(f.emoji||'🥣')}</span><div class="grow"><h2>${esc(f.name)}</h2><p>${esc(f.sourceName||f.category)} · per ${f.basis==='dose'?'dosis':'100 g'}</p></div><button class="icon-button favorite ${state.favorites.includes(f.id)?'on':''}" data-action="favorite" data-id="${esc(f.id)}" aria-label="Favoriet wisselen">${icon('star')}</button></div><form id="entry-form"><div class="form-grid"><label class="field">Hoeveelheid (${f.basis==='dose'?'dosis':'gram'})<input id="entry-amount" name="amount" type="number" min="0.01" max="100000" step="any" value="${entry?.amount||f.serving||100}" required autofocus></label><label class="field">Maaltijd<select name="meal">${MEALS.map(m=>`<option ${m===(f.basis==='dose'&&!entry?'Supplementen':addMeal)?'selected':''}>${m}</option>`).join('')}</select></label></div><div id="portion-preview">${portionPreview(f,entry?.amount||f.serving||100)}</div><p class="tiny muted mt16">${Object.values(f.values).filter(v=>Number.isFinite(v)).length} van ${NUTRIENTS.length-1} voedingswaarden bekend · onbekend is niet nul.</p>${f.allergens?`<div class="notice warning">Allergenen volgens bron: ${esc(f.allergens)}. Controleer altijd het etiket.</div>`:''}<div class="form-actions">${entry?`<button type="button" class="button ghost" data-action="delete-entry" data-id="${esc(entry.id)}">Verwijderen</button>`:''}<button type="submit" class="button primary">${icon('plus')}${entry?'Aanpassing opslaan':'Toevoegen aan dagboek'}</button></div></form>${f.source?`<div class="detail-section"><a href="${esc(f.source)}" target="_blank" rel="noopener">Productbron bekijken ↗</a></div>`:''}`);}
function portionPreview(f,amount){return `<div class="mini-grid">${['energy','protein','fiber'].map(id=>{const n=nutrientById(id),v=f.values[id];return `<div>${n.name}<strong>${v==null?'—':fmt(v*amount/(f.basis==='dose'?1:100),precision(n))} ${n.unit}</strong></div>`;}).join('')}</div>`;}
function foodDetail(id){const f=allFoods().find(f=>f.id===id);if(!f)return;modal('Productinformatie',`<div class="detail-hero"><span class="food-emoji">${esc(f.emoji)}</span><div class="grow"><h2>${esc(f.name)}</h2><p>Waarden per ${f.basis==='dose'?'dosis':'100 g'}</p></div><button class="icon-button favorite ${state.favorites.includes(id)?'on':''}" data-action="favorite" data-id="${esc(id)}" aria-label="Favoriet wisselen">${icon('star')}</button></div><div class="row wrap"><button class="button primary" data-action="choose-food" data-id="${esc(id)}">${icon('plus')}In dagboek</button>${state.foods.some(x=>x.id===id)?`<button class="button secondary" data-action="edit-food" data-id="${esc(id)}">Aanpassen</button><button class="icon-button" data-action="delete-food" data-id="${esc(id)}" aria-label="Eigen product verwijderen">${icon('trash')}</button>`:''}</div><table class="compact-table"><tbody>${NUTRIENTS.filter(n=>n.id!=='water').map(n=>`<tr><td>${n.name}</td><td>${f.values[n.id]==null?'Onbekend':fmt(f.values[n.id],precision(n))+' '+n.unit}</td></tr>`).join('')}</tbody></table>${f.ingredients?`<div class="detail-section"><h3>Ingrediënten</h3><p>${esc(f.ingredients)}</p></div>`:''}<p class="tiny muted mt16">${esc(f.sourceName||'Eigen invoer')} ${f.sourceCode?'· productcode '+esc(f.sourceCode):''}</p>${f.source?`<a class="small" href="${esc(f.source)}" target="_blank" rel="noopener">Bron bekijken ↗</a>`:''}`);}
function openRecipe(reset=true){if(reset)recipeParts=[];modal('Je eigen recept',`<form id="recipe-form"><label class="field">Naam van het recept<input name="recipeName" maxlength="160" required placeholder="Bijv. mijn ontbijtkom"></label><div class="notice">Voeg de gewichten van je ingrediënten toe. Vul daarna het totale eetbare gewicht van het bereide recept in. Alleen voedingswaarden die voor alle ingrediënten bekend zijn, worden berekend.</div><div class="row responsive"><label class="field grow">Ingrediënt<select id="recipe-food">${allFoods().filter(f=>f.basis!=='dose').map(f=>`<option value="${esc(f.id)}">${esc(f.name)}</option>`).join('')}</select></label><label class="field" style="width:90px">Gram<input id="recipe-amount" type="number" min="0.1" max="100000" step="any" value="100"></label><button type="button" class="button secondary" style="align-self:end" data-action="recipe-add">${icon('plus')}Toevoegen</button></div><div id="recipe-parts" class="mt16"></div><label class="field mt24">Totaal gewicht na bereiding (g)<input name="weight" type="number" min="1" max="100000" step="any" required placeholder="Inclusief opgenomen water, zonder verpakking"></label><div id="recipe-error" class="error-text"></div><div class="form-actions"><button class="button primary" type="submit">Recept bewaren</button></div></form>`);renderRecipeParts();}
function renderRecipeParts(){$('#recipe-parts').innerHTML=recipeParts.length?recipeParts.map((p,i)=>`<div class="recipe-part row"><span class="grow">${esc(p.food.name)}</span><span>${fmt(p.amount,1)} g</span><button type="button" class="icon-button" data-action="recipe-remove" data-value="${i}" aria-label="Ingrediënt verwijderen">${icon('close')}</button></div>`).join(''):'<p class="small muted">Nog geen ingrediënten toegevoegd.</p>';}
function installDialog(){modal(window.AndroidBridge?'VoedKompas op Android':'Installeer VoedKompas',`${window.AndroidBridge?'<div class="notice">Je gebruikt de geïnstalleerde Android-app. Het dagboek, de basisproducten en de uitleg werken volledig offline.</div>':'<div class="notice">Open de beveiligde website in Chrome op je Android-telefoon. Kies in het menu ⋮ voor <strong>App installeren</strong> of <strong>Toevoegen aan startscherm</strong>. Deze functie werkt alleen op een HTTPS-website of op deze computer via localhost.</div>'}<div class="detail-section"><h3>Je gegevens blijven bij jou</h3><p>Er is geen automatische synchronisatie. Maak een back-up in Instellingen voordat je de app verwijdert of van apparaat wisselt. Je browserdagboek en het dagboek in de Android-app zijn afzonderlijk; zet ze over met een back-up.</p></div><div class="detail-section"><h3>Offline en online</h3><p>Je dagboek en uitleg zijn offline beschikbaar. Voor barcodegegevens en bronpagina’s heb je internet nodig. De app verstuurt je voedingsdagboek nergens naartoe.</p></div>${installPrompt?'<button class="button primary" data-action="native-install">Nu installeren</button>':''}`);}
function download(name,type,text){if(window.AndroidBridge?.saveFile){window.AndroidBridge.saveFile(name,type,text);return;}const blob=new Blob([text],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),30000);}
window.onNativeSaveResult=success=>toast(success?'Bestand opgeslagen.':'Opslaan geannuleerd of niet gelukt.');
function exportCSV(){const dates=[...new Set([...state.entries.map(e=>e.date),...Object.keys(state.water)])].sort();const cell=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const rows=[['Datum','Dag compleet gemarkeerd',...NUTRIENTS.flatMap(n=>[`${n.name} (${n.unit})`,`Bekende producten ${n.name}`,`Totaal producten ${n.name}`])]];for(const date of dates){const d=daily(state,date,NUTRIENTS);rows.push([date,state.completed.includes(date)?'ja':'nee',...NUTRIENTS.flatMap(n=>{const v=d.values[n.id];return [v.known?String(Number(v.value.toFixed(4))).replace('.',','):'',v.known,v.total];})]);}download(`VoedKompas-dagtotalen-${dateKey()}.csv`,'text/csv;charset=utf-8','\uFEFF'+rows.map(r=>r.map(cell).join(';')).join('\r\n'));}
function startDemo(){if(demo)return;realState=state;state=emptyState();state.profile.name='';demo=true;const demoFoods=FOODS.filter(f=>f.values.energy!=null).slice(0,12);for(let i=0;i<7;i++){const date=shiftDate(dateKey(),-i);demoFoods.slice(i%3,i%3+5).forEach((f,j)=>state.entries.push({id:uid(),date,meal:MEALS[Math.min(j,3)],amount:[80,150,200,120,30][j],food:structuredClone(f)}));state.water[date]=[1500,1750,2000,1250,2000,1500,1750][i];if(i>0)state.completed.push(date);}selectedDate=dateKey();go('overview');toast('Voorbeeldmodus: alle getoonde registraties zijn fictief.');}
function confirmModal(title,text,action){modal(title,`<p class="small muted" style="line-height:1.9">${text}</p><div class="form-actions"><button class="button secondary" data-action="close-modal">Annuleren</button><button class="button danger" data-action="${esc(action)}">Bevestigen</button></div>`);}
document.addEventListener('click',async event=>{
  const external=event.target.closest('a[href^="https://"]');if(external&&window.AndroidBridge?.openUrl){event.preventDefault();window.AndroidBridge.openUrl(external.href);return;}
  const el=event.target.closest('[data-action],[data-page]');if(!el)return;if(el.dataset.page){event.preventDefault();go(el.dataset.page);return;}
  const {action,id,value,meal,date}=el.dataset;
  switch(action){
    case 'close-modal':closeModal();break;
    case 'day':selectedDate=shiftDate(selectedDate,Number(value));render();break;
    case 'add':openAdd(meal||'Ontbijt');break;
    case 'add-tab':addTab=id;renderAdd();break;
    case 'all-nutrients':go('nutrients');break;
    case 'nutrient':nutrientDetail(id);break;
    case 'nutrient-group':nutrientGroup=id;render();break;
    case 'choose-food':chooseFood(id);break;
    case 'food-detail':foodDetail(id);break;
    case 'edit-entry':chooseFood(null,id);break;
    case 'delete-entry':{const old=state.entries.find(e=>e.id===id);if(!old)break;state.entries=state.entries.filter(e=>e.id!==id);state.completed=state.completed.filter(d=>d!==old.date);save();if($('#modal').open)closeModal();render();toast('Product uit dagboek verwijderd.',()=>{state.entries.push(old);save();render();});break;}
    case 'favorite':state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();el.classList.toggle('on',state.favorites.includes(id));toast(state.favorites.includes(id)?'Toegevoegd aan favorieten.':'Uit favorieten verwijderd.');break;
    case 'show-favorites':{const list=filterFoods('','Favorieten');$('#food-results').innerHTML=list.length?list.map(f=>foodItem(f)).join(''):'<div class="empty">Nog geen favorieten. Tik bij een product op het sterretje.</div>';break;}
    case 'water':{const day=selectedDate,before=state.water[day]||0;state.water[day]=Math.min(30000,before+Number(value));save();render();toast(`${value} ml geregistreerd.`,()=>{state.water[day]=before;save();render();});break;}
    case 'water-edit':modal('Je drinkregistratie',`<form id="water-form"><label class="field">Totaal gedronken op deze dag (ml)<input name="water" type="number" min="0" max="30000" step="1" value="${state.water[selectedDate]||0}" required></label><div class="form-actions"><button class="button primary" type="submit">Opslaan</button></div></form>`);break;
    case 'save-note':state.notes[selectedDate]=$('#day-notes').value;save();toast('Notitie opgeslagen.');break;
    case 'complete-day':state.completed=state.completed.includes(selectedDate)?state.completed.filter(d=>d!==selectedDate):[...state.completed,selectedDate];save();render();break;
    case 'copy-day':{const yesterday=state.entries.filter(e=>e.date===shiftDate(selectedDate,-1));if(!yesterday.length){toast('Gisteren staan geen producten in je dagboek.');break;}confirmModal('Voeding van gisteren kopiëren?',`${yesterday.length} producten worden aan deze dag toegevoegd. Bestaande registraties blijven staan. Supplementen worden ook meegenomen; controleer of je ze echt hebt genomen.`,'confirm-copy');break;}
    case 'confirm-copy':{const copied=state.entries.filter(e=>e.date===shiftDate(selectedDate,-1)).map(e=>({...structuredClone(e),id:uid(),date:selectedDate}));state.entries.push(...copied);state.completed=state.completed.filter(d=>d!==selectedDate);save();closeModal();render();toast('Voeding van gisteren toegevoegd.');break;}
    case 'open-day':selectedDate=date;go('diary');break;
    case 'range':trendLength=Number(value);render();break;
    case 'library-category':libraryCategory=value;render();break;
    case 'new-food':openAdd('Ontbijt','custom');break;
    case 'edit-food':{const f=allFoods().find(f=>f.id===id);modal('Eigen product aanpassen',customForm(f.basis==='dose',f));break;}
    case 'delete-food':confirmModal('Eigen product verwijderen?','Het product verdwijnt uit je bibliotheek. Eerdere registraties in je dagboek blijven bewaard.',`confirm-delete-food:${id}`);break;
    case 'new-recipe':openRecipe();break;
    case 'recipe-add':{const food=allFoods().find(f=>f.id===$('#recipe-food').value),amount=Number($('#recipe-amount').value);if(!food||!Number.isFinite(amount)||amount<=0||amount>100000){toast('Vul een geldig gewicht in.');break;}recipeParts.push({food,amount});renderRecipeParts();break;}
    case 'recipe-remove':recipeParts.splice(Number(value),1);renderRecipeParts();break;
    case 'install':installDialog();break;
    case 'native-install':if(installPrompt){await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;closeModal();}break;
    case 'demo':startDemo();break;
    case 'exit-demo':state=realState;realState=null;demo=false;render();break;
    case 'export':download(`VoedKompas-backup-${dateKey()}${demo?'-voorbeeld':''}.json`,'application/json',JSON.stringify(state,null,2));break;
    case 'csv':exportCSV();break;
    case 'recovery':download('VoedKompas-herstelbestand.json','application/json',rawBackup);break;
    case 'import':if(demo){toast('Sluit eerst de voorbeeldmodus.');break;}confirmModal('Back-up terugzetten?','Kies hierna je VoedKompas-back-up. Een geldige back-up vervangt de huidige gegevens. Download eerst je huidige back-up als je die wilt bewaren.','choose-import');break;
    case 'choose-import':closeModal();$('#import-file').value='';$('#import-file').click();break;
    case 'reset-goals':confirmModal('Dagreferenties herstellen?','Je aangepaste referenties worden vervangen door de standaard EU-etiketreferenties en de voorbeelden voor drinken en vezels.','confirm-reset-goals');break;
    case 'confirm-reset-goals':state.goals={};state.profile.waterGoal=2000;save();closeModal();render();toast('Standaardreferenties hersteld.');break;
    case 'reset-data':confirmModal('Alle gegevens wissen?','Dit verwijdert het dagboek, je eigen producten, notities en voorkeuren van dit apparaat. Deze actie kan niet ongedaan worden gemaakt. Download zo nodig eerst een back-up.','confirm-reset-data');break;
    case 'confirm-reset-data':state=emptyState();loadError='';save();closeModal();render();toast('Lokale gegevens gewist.');break;
    default:if(action.startsWith('confirm-delete-food:')){const foodId=action.slice('confirm-delete-food:'.length);state.foods=state.foods.filter(f=>f.id!==foodId);state.favorites=state.favorites.filter(f=>f!==foodId);save();closeModal();render();toast('Eigen product verwijderd.');}
  }
});
document.addEventListener('input',event=>{const t=event.target;if(t.id==='food-search'){const list=filterFoods(t.value,'Alles');$('#food-results').innerHTML=list.length?list.map(f=>foodItem(f)).join(''):'<div class="empty">Geen product gevonden. Kies Eigen product of Barcode om het toe te voegen.</div>';}if(t.id==='library-search'){librarySearch=t.value;$('#library-results').innerHTML=libraryResults();}if(t.id==='entry-amount'&&selectedFood){$('#portion-preview').innerHTML=portionPreview(selectedFood,Number(t.value)||0);}});
document.addEventListener('change',async event=>{const t=event.target;if(t.id==='selected-date'&&/^\d{4}-\d{2}-\d{2}$/.test(t.value)){selectedDate=t.value;render();}if(t.id==='trend-nutrient'){trendNutrient=t.value;render();}if(t.id==='import-file'&&t.files[0]){try{if(t.files[0].size>25e6)throw new Error('De back-up is groter dan 25 MB.');const imported=validateBackup(JSON.parse(await t.files[0].text()),NUTRIENTS);localStorage.setItem(STORAGE,JSON.stringify(imported));state=imported;loadError='';render();toast('Back-up teruggezet.');}catch(e){toast('Import niet uitgevoerd: '+e.message);}}});
document.addEventListener('submit',async event=>{
  event.preventDefault();const form=event.target,fd=new FormData(form);
  if(form.id==='entry-form'){const amount=Number(fd.get('amount'));if(!Number.isFinite(amount)||amount<=0||amount>100000||!selectedFood)return;const old=state.entries.find(e=>e.id===editEntryId),entry={id:old?.id||uid(),date:old?.date||selectedDate,meal:fd.get('meal'),amount,food:structuredClone(selectedFood)};if(old)state.entries[state.entries.indexOf(old)]=entry;else state.entries.push(entry);state.completed=state.completed.filter(d=>d!==entry.date);save();closeModal();render();toast(old?'Hoeveelheid aangepast.':'Toegevoegd aan je dagboek.');}
  if(form.id==='custom-form'){try{const values={};for(const n of NUTRIENTS){const v=fd.get('nutrient-'+n.id);if(v!==null&&v!=='')values[n.id]=Number(v);}const f=cleanFood({id:form.dataset.edit||uid(),name:fd.get('foodName'),basis:form.dataset.basis,emoji:form.dataset.basis==='dose'?'💊':'🥣',category:form.dataset.basis==='dose'?'Supplementen':'Eigen producten',serving:Number(fd.get('serving')),values,sourceName:'Eigen invoer · controleer je etiket'},NUTRIENTS);state.foods=state.foods.filter(x=>x.id!==f.id);state.foods.unshift(f);save();if(form.dataset.edit){closeModal();render();toast('Product aangepast. Eerdere dagboekregels blijven gelijk.');}else{render();chooseFood(f.id);}}catch(e){$('#custom-error').textContent=e.message;}}
  if(form.id==='barcode-form'){if(barcodeBusy)return;barcodeBusy=true;const button=form.querySelector('button[type="submit"]');button.disabled=true;$('#barcode-status').innerHTML='<div class="notice">Product opzoeken…</div>';try{const code=fd.get('barcode');const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),12000);let response;try{response=await fetch(`https://world.openfoodfacts.org/api/v2/product/${encodeURIComponent(code)}.json?fields=product_name,product_name_nl,nutriments,ingredients_text,ingredients_text_nl,allergens`,{signal:controller.signal});}finally{clearTimeout(timeout);}if(!response.ok)throw new Error('De productdienst is tijdelijk niet bereikbaar.');const data=await response.json();if(data.status!==1)throw new Error('Geen product gevonden. Voeg het zelf toe met het etiket.');const f=fromOpenFoodFacts(data.product,code,NUTRIENTS);state.foods=state.foods.filter(x=>x.id!==f.id);state.foods.unshift(f);save();render();chooseFood(f.id);}catch(e){if($('#barcode-status'))$('#barcode-status').innerHTML=`<div class="notice error">${esc(e.name==='AbortError'?'Het zoeken duurt te lang. Probeer opnieuw of voeg het product zelf toe.':e.message||'Geen verbinding. Probeer later opnieuw.')}</div>`;}finally{barcodeBusy=false;if(button.isConnected)button.disabled=false;}}
  if(form.id==='recipe-form'){try{const f=recipeFood(fd.get('recipeName'),recipeParts,Number(fd.get('weight')),NUTRIENTS);state.foods.unshift(f);save();render();chooseFood(f.id);toast('Recept bewaard in je bibliotheek.');}catch(e){$('#recipe-error').textContent=e.message;}}
  if(form.id==='water-form'){const value=Number(fd.get('water'));if(Number.isFinite(value)&&value>=0&&value<=30000){state.water[selectedDate]=value;save();closeModal();render();toast('Drinkregistratie aangepast.');}}
  if(form.id==='settings-form'){state.profile.name=String(fd.get('name')).trim();for(const n of NUTRIENTS){const value=Number(fd.get('goal-'+n.id));if(Number.isFinite(value)&&value>0&&value<=1e6)state.goals[n.id]=value;}save();render();toast('Voorkeuren opgeslagen.');}
});
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(pageNames[p])go(p);});
window.addEventListener('online',()=>{if(!$('#modal').open)render();});window.addEventListener('offline',()=>{if(!$('#modal').open)render();});
$('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const r=event.target.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();}});
if('serviceWorker' in navigator&&!window.AndroidBridge)navigator.serviceWorker.register('./sw.js').catch(()=>{});
window.appBack=()=>{if($('#modal').open){closeModal();return true;}if(page!=='overview'){go('overview');return true;}return false;};
render();
